#!/usr/bin/env python3
"""case-scaleup-1111 r2 step 4: plan/eval2/case-scaleup-1111/r2/PLAN.md from $SCR/{cands,emit}.pkl and stale.tsv."""
import collections, pickle, re
G = '/local/home/mkhoshechin/Documents/github-jmc/'; SCR = '/local/home/mkhoshechin/tmp/case-scaleup-1111-r2/'
X = pickle.load(open(SCR + 'cands.pkl', 'rb')); E = pickle.load(open(SCR + 'emit.pkl', 'rb'))
S = [l.split('\t') for l in open(SCR + 'stale.tsv').read().splitlines()[1:]]
sz = lambda c: ','.join(map(str, c))
cand = E['cand']; c = collections.Counter((x[1], x[2], x[5]) for x in cand); h = collections.defaultdict(float)
for x in cand: h[(x[1], x[2])] += x[3]
L = ['# Case-study scale-up 2026-11-11, round 2: plan (generated by daavar/scripts/case-scaleup-1111-r2/md.py; estimates are planning numbers, R10)', '',
     'Brief: ../BRIEF.md (binds this round). Round 1: ../PLAN.md. Rows: daavar/cluster/campaign/case-scaleup-1111/r2/part{A,B,C}-<class>-pool.rows(.rows.tsv); a file exists only for a non-empty (part, class). One line per row: candidates.tsv (column part).',
     'Scripts: daavar/scripts/case-scaleup-1111-r2/{load,gen,stale,emit,md}.py (load.py and the helper half of gen.py copied from round 1). Inputs: brain-data a2f698d96, tmp/sweep-1111 running-live.tsv/pending-dedup.tsv (about 01:50), every rows file under cluster/campaign/ (round 1 included, treated as pending).', '',
     '## Counts (rows per part, class and priority; estimated hours on that class)', '', '| part | class | P1 | P2 | P3 | est h |', '|---|---|---|---|---|---|']
for p in 'ABC':
    for k in ('brain', 'volta', 'pinky'):
        if any(c[(p, k, q)] for q in (1, 2, 3)): L.append(f'| {p} | {k} | {c[(p,k,1)]} | {c[(p,k,2)]} | {c[(p,k,3)]} | {h[(p,k)]:.1f} |')
L += ['', f'Total {len(cand)} rows, {sum(h.values()):.1f} estimated hours. Part C groups that share an export with a Part A or B join sit in that part\'s file (a group stays on one host); the part column of candidates.tsv is per row. '
      f'Later (blocked by a running/pending export): {len(X["later"])} sizes. Infeasible: {len(X["infeas"])} sizes blocked by a limit or a repeating failure, {len(E["dropped"])} over the budget by estimate.', '',
      '**The supply is far below 75 slots x 40 h.** Almost every further step of every family is blocked by an export of the same program at a size <= it that is running, pending (CASE) or queued by round 1, or by an export that already hit the 48 h limit / failed with exit 101/126. See "Later" for what unblocks when.', '',
      '## Assumptions', '',
      '1. As round 1 (../PLAN.md assumptions 1, 2, 4-10), except: steps +1, +2 and +3 on each size axis of each maximal measured size; no "+2 only when cheap" filter; budget 36 h on a brain node (24 h on pinky/volta, which count x2), peak <= 230/180/70 GB, a JMC export also <= 17 x heap (brain 204, volta 272, pinky 136 GB; binding only on brain).',
      '2. Round 1 rows (cluster/campaign/case-scaleup-1111/*-pool.rows) count as pending. A running/pending export blocks a candidate only when the export key has no ok record at that size (an export measured elsewhere is known to finish; its pending duplicate is no uncertainty).',
      '3. A new size proposed in this round blocks the higher steps of the same export key (they go to "later", waiting for the row of this round), since the rule forbids stacking on an unmeasured export.',
      '4. Part A = the join instance at C sits in rows files only (no brain-data record, not running, not pending), or its records failed for a non-repeating reason. Repeating: a timeout at >= 172800 s, exit 101 or 126, a format refusal (`failed: ... must:` or `refused`), or `skipped:` because of such a failure of an export it reads; an export key with such a failure at a size <= C (and no ok record there) blocks C as infeasible. exit-143 (stopped), exit-127, exit-2, `invalid: killed`, `foreign load` are not repeating; `invalid: jmc cap` counts as a limit (as round 1).',
      '5. Part A ids: round-1 shape `<join>.cinf.m` (tier cinf); when that id is taken, `.r2`/`.rN` is appended (round-1 convention, after `.m`).',
      '6. Part C = joins with prefix XJ1/XJ2/XC1/XC2/XT1/XT2 or reading an XCE/XJE export. JMC exports get the class heap (-Xmx8g/16g/12g); their time is the brain-equivalent estimate (one export at a time on pinky/volta, three on brain: placement, not row time).',
      '7. Cheap exports (< 60 s at P) without a measured step along the axis take the largest step ratio of the same export along another axis (round 1 blocked them).',
      '8. Priority as round 1: 1 = Phase B (OmniPaxos, raft-rs, MicroRaft) or every measured size conformed; 3 = a join reading a JMC export, or a 24-36 h row; else 2. Exports inherit their group\'s priority.', '']
# Part A audit
res = {}
for x in cand:
    if x[10] == 'join': res[(x[6], x[9])] = x[0]
L += ['## Part A: round-1 "exists" entries, per entry', '', '| family | size | round-1 id | finding | r2 |', '|---|---|---|---|---|']
lat = {(l['fam'], sz(l['C'])): l['why'] for l in X['later']}; inf = {(l['fam'], sz(l['C'])): l['why'] for l in X['infeas']}
for fam, s, i, cl, det in S:
    out = res.get((fam, s)); r2 = f'proposed `{out}`' if out else (f'later: {lat[(fam, s)]}' if (fam, s) in lat else (f'infeasible: {inf[(fam, s)]}' if (fam, s) in inf else '-'))
    if cl in ('pending', 'running', 'pending-r1'): r2 = 'not proposed (live)'
    L.append(f'| {fam} | {s} | `{i}` | {cl}: {det} | {r2} |')
L += ['', '## Proposed rows', '', '| id | part | class | est h | est GB | prio | reason |', '|---|---|---|---|---|---|---|']
for x in cand: L.append(f'| `{x[0]}` | {x[1]} | {x[2]} | {x[3]:.2f} | {x[4]:.2f} | {x[5]} | {x[7]} |')
L += ['', '## Later (queue when the awaited export lands; same size = the join can be appended to the host of that export now)', '',
      '| part | family | from -> size | step | waits for |', '|---|---|---|---|---|']
for l in sorted(X['later'], key=lambda l: (l['part'], l['fam'], l['C'])):
    same = ' (same size)' if re.search(r' at ' + re.escape(sz(l['C'])) + r'( |$)', l['why']) else ''
    L.append(f"| {l['part']} | {l['fam']} | {sz(l['P'])} -> {sz(l['C'])} | +{l['step']} | {l['why']}{same} |")
L += ['', '## Infeasible', '', '### Over the budget by estimate (> 36 h or > 230 GB on brain, or no class fits)', '']
for cc in E['dropped']: L.append(f"- {cc['part']} {cc['fam']} {sz(cc['P'])} -> {sz(cc['C'])}: worst row {cc['worst_h']:.1f} h, peak {cc['peak']:.1f} GB (" + '; '.join(e['basis'] for e in cc['eplan']) + ')')
L += ['', '### Blocked by a limit or a repeating failure at a size <= C (Part C: the 48 h limit or jmc cap reached at a smaller size)', '']
for l in sorted(X['infeas'], key=lambda l: (l['part'], l['fam'], l['C'])): L.append(f"- {l['part']} {l['fam']} {sz(l['C'])}: {l['why']}")
L += ['', '## Families left out', '', f"{collections.Counter(X['left'].values()).most_common()}", '']
L += ['## Other notes per family', '']
for fam, ns in sorted(X['notes'].items()): L.append(f'- {fam}: ' + ' | '.join(ns))
open(G + 'plan/eval2/case-scaleup-1111/r2/PLAN.md', 'w').write('\n'.join(L) + '\n'); print(len(L), 'lines')
